static int
pair_coalescence_covered_span(const tsk_treeseq_t *self, tsk_size_t num_windows,
    const double *windows, double *covered_span)
{
    int ret = 0;
    double left, right, overlap;
    tsk_id_t w = 0;
    tsk_id_t tree_num_edges = 0;
    tsk_tree_position_t tree_pos;

