def insert_gaps(ts, gaps):
    """Return a ts with empty intervals inserted at existing breakpoints.
    gaps: list of (position, width). Edges straddling a gap are split and
    the mapped topology/spans of all non-empty intervals are preserved."""
    tables = ts.tables
    gap_at = {}
    for p, wd in gaps:
        gap_at[p] = gap_at.get(p, 0.0) + wd
    pts = sorted(gap_at)

    def shift_left(x):
        return x + sum(gap_at[p] for p in pts if p <= x)

    def shift_right(x):
        return x + sum(gap_at[p] for p in pts if p < x)

    new = tskit.TableCollection(sequence_length=tables.sequence_length
                                + sum(gap_at.values()))
    new.populations.metadata_schema = tables.populations.metadata_schema
    for row in tables.populations:
        new.populations.add_row(metadata=row.metadata)
    for row in tables.individuals:
        new.individuals.add_row(flags=row.flags, location=row.location,
                                parents=row.parents, metadata=row.metadata)
    for row in tables.nodes:
        new.nodes.add_row(flags=row.flags, time=row.time,
                          population=row.population, individual=row.individual,
                          metadata=row.metadata)
    for e in tables.edges:
        cuts = [p for p in pts if e.left < p < e.right]
        xs = [e.left] + cuts + [e.right]
        for a, b in zip(xs, xs[1:]):
            new.edges.add_row(shift_left(a), shift_right(b), e.parent, e.child)
    new.sort()
    return new.tree_sequence()

