+/* Computes, for each window, the span of sequence covered by at least one
+ * edge (the non-missing span). Missing intervals - where the tree is
+ * undefined - do not contribute to the statistics, so the corresponding
+ * span must also be excluded from the span normalising denominator.
+ */
+static int
+pair_coalescence_covered_span(const tsk_treeseq_t *self, tsk_size_t num_windows,
+    const double *windows, double *covered_span)
+{
+    int ret = 0;
+    double left, right, overlap;
+    tsk_id_t w = 0;
+    tsk_id_t tree_num_edges = 0;
+    tsk_tree_position_t tree_pos;
+
+    tsk_memset(&tree_pos, 0, sizeof(tree_pos));
+    ret = tsk_tree_position_init(&tree_pos, self, 0);
+    if (ret != 0) {
+        goto out;
+    }
+    while (true) {
+        tsk_tree_position_next(&tree_pos);
+        if (tree_pos.index == TSK_NULL) {
+            break;
+        }
+        tree_num_edges += (tree_pos.in.stop - tree_pos.in.start)
+                          - (tree_pos.out.stop - tree_pos.out.start);
+        if (tree_num_edges == 0) {
+            continue; /* missing interval: no tree is defined here */
+        }
+        left = tree_pos.interval.left;
+        right = tree_pos.interval.right;
+        while (w < (tsk_id_t) num_windows && windows[w + 1] <= left) {
+            w++;
+        }
+        while (w < (tsk_id_t) num_windows && left < right) {
+            overlap = TSK_MIN(right, windows[w + 1]) - left;
+            covered_span[w] += overlap;
+            left = windows[w + 1];
+            if (left < right) {
+                w++;
+            } else {
+                break;
+            }
+        }
+    }
+out:
+    tsk_tree_position_free(&tree_pos);
+    return ret;
+}
